import { useEffect, useState } from 'react';
import { useApi } from '../app/api-context.js';
import type { ApiClient } from '../lib/api.js';

const caches = new WeakMap<ApiClient, Map<string, Promise<string | null>>>();

/**
 * The Microsoft account's Azure DevOps profile picture as a data URL, or null
 * to keep initials (signed out, unavailable, or an auto-generated placeholder).
 * One request per account and API client; failures are retried on next use.
 */
export function useAzureAvatar(org: string, account: string | null, connected: boolean): string | null {
  const api = useApi();
  const [dataUrl, setDataUrl] = useState<string | null>(null);
  useEffect(() => {
    setDataUrl(null);
    if (!connected || !account) return;
    const cache = caches.get(api) ?? new Map<string, Promise<string | null>>();
    caches.set(api, cache);
    const key = account.toLowerCase();
    let pending = cache.get(key);
    if (!pending) {
      pending = Promise.resolve().then(() => api.getAzureAvatar(org)).then((avatar) => avatar.autoGenerated ? null : avatar.dataUrl);
      cache.set(key, pending);
      pending.catch(() => cache.delete(key));
    }
    let active = true;
    pending.then((value) => { if (active) setDataUrl(value); }, () => undefined);
    return () => { active = false; };
  }, [api, org, account, connected]);
  return dataUrl;
}
